import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.D7Pdja0E.js";const m=JSON.parse('{"title":"MCP (Claude / 외부 클라이언트 연결)","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/modules-mcp.md","filePath":"04-org-admin-guide/modules-mcp.md","lastUpdated":1780579853000}'),l={name:"04-org-admin-guide/modules-mcp.md"};function r(i,e,c,h,n,s){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="mcp-claude-외부-클라이언트-연결" tabindex="-1">MCP (Claude / 외부 클라이언트 연결) <a class="header-anchor" href="#mcp-claude-외부-클라이언트-연결" aria-label="Permalink to &quot;MCP (Claude / 외부 클라이언트 연결)&quot;">​</a></h1><p>워크허브는 <strong>Model Context Protocol (MCP)</strong> 서버를 내장 노출하여 Claude Desktop / Claude Code / 기타 MCP 호환 클라이언트가 본인 워크허브 계정의 채널 / 태스크 / Gmail / Drive / 재무 등을 직접 조작할 수 있게 해줍니다.</p><blockquote><p><strong>MCP 는 항상 노출되는 시스템 기능</strong>: 별도 모듈 토글이 없습니다. 워크허브 백엔드가 떠 있는 한 <code>/api/mcp</code> 엔드포인트는 항상 활성. 단, <strong>사용자가 MCP 토큰을 발급하기 전까지는 누구도 접속할 수 없으므로</strong> 사실상 사용자 단위로 opt-in 됩니다.</p></blockquote><hr><h2 id="_1-mcp-가-무엇인가" tabindex="-1">1. MCP 가 무엇인가 <a class="header-anchor" href="#_1-mcp-가-무엇인가" aria-label="Permalink to &quot;1. MCP 가 무엇인가&quot;">​</a></h2><p>Model Context Protocol — Anthropic 이 공개한 표준 (<a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">https://modelcontextprotocol.io</a>). LLM 클라이언트가 외부 시스템의 데이터·도구를 호출할 수 있도록 JSON-RPC 2.0 + SSE 기반의 인터페이스를 정의합니다.</p><p>워크허브 MCP 서버는 <strong>본인 권한 한도 안에서</strong> 다음을 노출:</p><ul><li>채널 / 메시지 / 태스크 조회 / 작성</li><li>Gmail 메일 분류 / 발신 (Gmail 모듈 활성 + 본인 OAuth 동의 시)</li><li>Drive 파일 첨부 / 권한 부여 (Drive 모듈 활성 + 본인 OAuth 동의 시)</li><li>재무 (경비 / 청구 / 계약) 조회 / 작성</li><li>CRM 명함 / 미팅 / 고객 조회</li></ul><hr><h2 id="_2-사용자-pat-personal-access-token-정책" tabindex="-1">2. 사용자 PAT (Personal Access Token) 정책 <a class="header-anchor" href="#_2-사용자-pat-personal-access-token-정책" aria-label="Permalink to &quot;2. 사용자 PAT (Personal Access Token) 정책&quot;">​</a></h2><h3 id="_2-1-누가-발급할-수-있나" tabindex="-1">2.1 누가 발급할 수 있나 <a class="header-anchor" href="#_2-1-누가-발급할-수-있나" aria-label="Permalink to &quot;2.1 누가 발급할 수 있나&quot;">​</a></h3><p><strong>모든 사용자</strong> — 본인 프로필 화면에서 직접 발급 가능. 기관관리자 승인 불필요.</p><ul><li>위치: 워크허브 → 프로필 (<code>/app/profile</code>) → 화면 하단 <strong>&quot;MCP 토큰&quot;</strong> 섹션</li><li>토큰은 발급 시 1회만 표시 (재조회 불가)</li><li>만료 옵션: 30 / 90 / 365일 또는 무기한</li><li>본인이 언제든 [폐기] 가능</li></ul><p>자세한 사용자 가이드: <a href="./../02-user-guide/claude-mcp-integration.html">Claude / MCP 클라이언트 연결</a></p><h3 id="_2-2-oauth-클라이언트-등록-claude-desktop-oauth" tabindex="-1">2.2 OAuth 클라이언트 등록 (Claude Desktop OAuth) <a class="header-anchor" href="#_2-2-oauth-클라이언트-등록-claude-desktop-oauth" aria-label="Permalink to &quot;2.2 OAuth 클라이언트 등록 (Claude Desktop OAuth)&quot;">​</a></h3><p>Claude Desktop 은 <code>mcp-remote</code> 를 통해 OAuth 2.1 + PKCE 흐름으로 워크허브에 접속합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>값 / 위치</th></tr></thead><tbody><tr><td>OAuth Discovery</td><td><code>https://&lt;워크허브 도메인&gt;/.well-known/oauth-authorization-server</code> (자동)</td></tr><tr><td>Authorization endpoint</td><td><code>/oauth/authorize</code> (워크허브 자동 제공)</td></tr><tr><td>Token endpoint</td><td><code>/oauth/token</code> (워크허브 자동 제공)</td></tr><tr><td>Client Registration</td><td>Dynamic Client Registration (RFC 7591) — Claude Desktop 이 자동 등록</td></tr><tr><td>발급된 토큰</td><td>본인 프로필 → MCP 토큰 화면에 <code>OAuth: wh-...</code> 이름으로 표시</td></tr></tbody></table><p>→ Claude Desktop / Claude Code 모두 워크허브 측 별도 설정 불필요. 사용자가 클라이언트 측에서 <code>mcp-remote</code> 로 URL 만 지정하면 OAuth 흐름이 자동 진행됩니다.</p><hr><h2 id="_3-mcp-도구-tools-일람" tabindex="-1">3. MCP 도구 (Tools) 일람 <a class="header-anchor" href="#_3-mcp-도구-tools-일람" aria-label="Permalink to &quot;3. MCP 도구 (Tools) 일람&quot;">​</a></h2><p>연결된 클라이언트가 자동 인식하는 도구 목록 (사용자 권한 / 모듈 활성 상태에 따라 가시성 결정):</p><h3 id="워크허브-코어-항상" tabindex="-1">워크허브 코어 (항상) <a class="header-anchor" href="#워크허브-코어-항상" aria-label="Permalink to &quot;워크허브 코어 (항상)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>분류</th><th>Tool</th></tr></thead><tbody><tr><td>채널 / 메시지</td><td><code>list_channels</code>, <code>list_thread</code>, <code>read_messages</code>, <code>send_message</code>, <code>add_reaction</code>, <code>remove_reaction</code>, <code>pin_message</code>, <code>unpin_message</code></td></tr><tr><td>태스크</td><td><code>list_tasks</code>, <code>create_task</code>, <code>update_task</code></td></tr><tr><td>사용자</td><td><code>get_user_info</code>, <code>list_users</code>, <code>get_dm_room</code></td></tr><tr><td>검색</td><td><code>search</code></td></tr></tbody></table><h3 id="google-연동-gmail-drive-모듈-활성-본인-oauth-시" tabindex="-1">Google 연동 (Gmail / Drive 모듈 활성 + 본인 OAuth 시) <a class="header-anchor" href="#google-연동-gmail-drive-모듈-활성-본인-oauth-시" aria-label="Permalink to &quot;Google 연동 (Gmail / Drive 모듈 활성 + 본인 OAuth 시)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>의존 모듈</th></tr></thead><tbody><tr><td><code>list_modules</code>, <code>list_shared_drives</code>, <code>attach_drive_file</code></td><td>Drive</td></tr><tr><td><code>gmail_list_threads</code>, <code>gmail_get_message</code>, <code>gmail_get_thread</code>, <code>gmail_modify_labels</code>, <code>gmail_send</code>, <code>gmail_list_message_attachments</code>, <code>gmail_import_attachment</code></td><td>Gmail (+ Drive for import)</td></tr><tr><td><code>tag_email</code>, <code>mark_email_processed</code></td><td>Gmail</td></tr><tr><td><code>create_task_from_email</code>, <code>create_expense_from_email</code></td><td>Gmail (+ Finance for expense)</td></tr></tbody></table><h3 id="재무-연동-재무-모듈-활성-시" tabindex="-1">재무 연동 (재무 모듈 활성 시) <a class="header-anchor" href="#재무-연동-재무-모듈-활성-시" aria-label="Permalink to &quot;재무 연동 (재무 모듈 활성 시)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>용도</th></tr></thead><tbody><tr><td><code>list_finance_clients</code>, <code>list_finance_contracts</code>, <code>list_finance_expenses</code>, <code>list_finance_billing_items</code>, <code>list_finance_receivables</code>, <code>list_finance_sales_ledger</code>, <code>get_finance_summary</code></td><td>조회</td></tr><tr><td><code>create_finance_client</code>, <code>create_finance_contract</code>, <code>create_finance_expense</code>, <code>update_finance_expense</code>, <code>record_billing_payment</code>, <code>attach_invoice_to_billing</code>, <code>attach_receipt_to_expense</code></td><td>작성</td></tr></tbody></table><p>→ Gmail / Drive / Finance / CRM 등 모듈 비활성 시 해당 도구는 호출 시 403 (모듈 비활성).</p><p>자세한 사용자 가이드: <a href="./../02-user-guide/gmail-module.html#5-mcp--claude-스킬로-메일-자동-분류-">Gmail 모듈 — 5. MCP + Claude 스킬</a></p><hr><h2 id="_4-권한-모델-중요" tabindex="-1">4. 권한 모델 (중요) <a class="header-anchor" href="#_4-권한-모델-중요" aria-label="Permalink to &quot;4. 권한 모델 (중요)&quot;">​</a></h2><ul><li>발급된 토큰은 <strong>본인 계정의 모든 권한</strong> 을 그대로 가집니다 (role, 소속 채널, OAuth scope 등)</li><li>본인이 워크허브 UI 에서 못 하는 작업은 MCP 도 못 함 (RBAC 동일 적용)</li><li><strong>org_admin 토큰은 특히 주의</strong> — Claude 가 모듈 활성화 / 사용자 추가까지 호출 가능</li><li>한 토큰은 한 사용자의 한 기관 컨텍스트 — 다른 기관 데이터에 접근 불가</li></ul><hr><h2 id="_5-보안-운영-권장사항" tabindex="-1">5. 보안 / 운영 권장사항 <a class="header-anchor" href="#_5-보안-운영-권장사항" aria-label="Permalink to &quot;5. 보안 / 운영 권장사항&quot;">​</a></h2><h3 id="토큰-보관-사용자-책임" tabindex="-1">토큰 보관 (사용자 책임) <a class="header-anchor" href="#토큰-보관-사용자-책임" aria-label="Permalink to &quot;토큰 보관 (사용자 책임)&quot;">​</a></h3><ul><li>토큰은 <strong>암호와 동일한 보안 수준</strong> 으로 다룰 것 (Keychain / 1Password 등)</li><li>평문으로 채팅 / 이메일 / 문서 / Git 에 노출 금지</li></ul><h3 id="폐기-경로" tabindex="-1">폐기 경로 <a class="header-anchor" href="#폐기-경로" aria-label="Permalink to &quot;폐기 경로&quot;">​</a></h3><table tabindex="0"><thead><tr><th>경로</th><th>누가</th></tr></thead><tbody><tr><td>워크허브 → 프로필 → MCP 토큰 → [폐기]</td><td>본인</td></tr><tr><td>사용자 비활성화 (퇴사)</td><td>기관관리자 — 사용자 계정 비활성 시 토큰 자동 무효화</td></tr><tr><td>시스템 장애 시 일괄 폐기</td><td>시스템관리자 (별도 운영 작업)</td></tr></tbody></table><h3 id="활동-모니터링" tabindex="-1">활동 모니터링 <a class="header-anchor" href="#활동-모니터링" aria-label="Permalink to &quot;활동 모니터링&quot;">​</a></h3><ul><li>각 토큰의 <strong>마지막 사용 시각</strong> 이 화면에 표시</li><li>본인이 사용 안 한 시각에 활동이 보이면 → 즉시 폐기 + 비밀번호 변경</li><li>(Future) 토큰별 호출 audit log — 현재는 시스템 audit 에만 기록</li></ul><h3 id="폐기-권장-시점" tabindex="-1">폐기 권장 시점 <a class="header-anchor" href="#폐기-권장-시점" aria-label="Permalink to &quot;폐기 권장 시점&quot;">​</a></h3><ul><li>사용 기기 분실 / 도난</li><li>노트북 양도 / 폐기 전</li><li>정기 보안 점검 (3~6개월)</li></ul><hr><h2 id="_6-모듈-시스템-비활성화-시-영향" tabindex="-1">6. 모듈 / 시스템 비활성화 시 영향 <a class="header-anchor" href="#_6-모듈-시스템-비활성화-시-영향" aria-label="Permalink to &quot;6. 모듈 / 시스템 비활성화 시 영향&quot;">​</a></h2><p>MCP 자체는 모듈 토글이 없으므로 끌 수 없습니다. 단:</p><table tabindex="0"><thead><tr><th>작업</th><th>효과</th></tr></thead><tbody><tr><td>사용자가 본인 토큰 전부 [폐기]</td><td>본인 측 MCP 호출만 즉시 불가</td></tr><tr><td>기관관리자가 Gmail 모듈 OFF</td><td>모든 사용자의 <code>gmail_*</code> 도구가 403 (다른 도구는 정상)</td></tr><tr><td>기관관리자가 Drive 모듈 OFF</td><td>모든 사용자의 <code>attach_drive_file</code> 등이 403</td></tr><tr><td>기관관리자가 재무 모듈 OFF</td><td>모든 사용자의 <code>finance_*</code> 도구가 403</td></tr><tr><td>시스템관리자가 MCP 엔드포인트 비활성</td><td>운영 환경변수 조정 — 전체 기관 영향 (시스템관리자 영역)</td></tr></tbody></table><hr><h2 id="_7-트러블슈팅" tabindex="-1">7. 트러블슈팅 <a class="header-anchor" href="#_7-트러블슈팅" aria-label="Permalink to &quot;7. 트러블슈팅&quot;">​</a></h2><h3 id="사용자가-401-unauthorized-404-not-found" tabindex="-1">사용자가 &quot;401 Unauthorized&quot; / &quot;404 Not Found&quot; <a class="header-anchor" href="#사용자가-401-unauthorized-404-not-found" aria-label="Permalink to &quot;사용자가 &quot;401 Unauthorized&quot; / &quot;404 Not Found&quot;&quot;">​</a></h3><ul><li>URL 의 <code>/api/mcp</code> 누락 (자주 발생)</li><li>토큰 폐기됨 / 만료됨 — 새로 발급</li><li>자세히: <a href="./../02-user-guide/claude-mcp-integration.html#자주-막히는-곳">사용자 가이드 — 자주 막히는 곳</a></li></ul><h3 id="claude-desktop-oauth-가-동의-화면이-안-보이고-로그인-화면" tabindex="-1">Claude Desktop OAuth 가 &quot;동의 화면이 안 보이고 로그인 화면&quot; <a class="header-anchor" href="#claude-desktop-oauth-가-동의-화면이-안-보이고-로그인-화면" aria-label="Permalink to &quot;Claude Desktop OAuth 가 &quot;동의 화면이 안 보이고 로그인 화면&quot;&quot;">​</a></h3><ul><li>사용자가 워크허브에 미리 로그인 → 자동으로 동의 화면 redirect</li><li>본인이 시도하는 사용자가 다른 계정으로 워크허브에 로그인돼 있으면 의도와 다른 계정의 토큰이 발급될 수 있음</li></ul><h3 id="tool-호출-시-권한-부족" tabindex="-1">Tool 호출 시 권한 부족 <a class="header-anchor" href="#tool-호출-시-권한-부족" aria-label="Permalink to &quot;Tool 호출 시 권한 부족&quot;">​</a></h3><ul><li>본인이 그 작업을 워크허브 UI 에서 못 하면 MCP 도 동일하게 거부 (RBAC 정상 동작)</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./../02-user-guide/claude-mcp-integration.html">Claude / MCP 클라이언트 연결 (사용자 가이드)</a> — 사용자 토큰 발급 / Claude Desktop / Code 설정</li><li><a href="./../02-user-guide/gmail-module.html#5-mcp--claude-스킬로-메일-자동-분류-">Gmail 모듈 (사용자 가이드) — 5. MCP 스킬</a> — 메일 트리아지 스킬 예시</li><li><a href="./modules-gmail.html">Gmail 모듈 (관리자)</a> — 모듈 활성화 (MCP <code>gmail_*</code> 도구 의존)</li><li><a href="./modules-gdrive.html">Drive 모듈 (관리자)</a> — 모듈 활성화 (MCP <code>attach_drive_file</code> 등 의존)</li></ul>',57)])])}const _=t(l,[["render",r]]);export{m as __pageData,_ as default};
